/* ---------------------------------------------------------------------
Modals

Controls the markup construction, resizing, positioning,
spawning, loading of inline or ajax content

All inline modals should be given a unique ID.

To spawn an inline modal on page load, put a class of "js-auto-spawn" on your container. Must
have a unique ID on the container.

To spawn a modal from a link, use the class of "js-spawn-modal" on your anchor. The href of this
anchor should point to the ID of an inline modal (include the hash mark), or to a URL of
a modal to be loaded via ajax.

Any element can close a modal on click if it has the CSS class of "js-close-modal"

//// Programatically controlling modals:
NERD.Modals.loadModal('#id') or NERD.Modals.loadModal('url')
NERD.Modals.closeModal()

//// Inline modal example:
<a href="#my-inline-modal" class="js-spawn-modal">I will spawn the modal below</a>
<div id="my-inline-modal" class="inline-modal">Hello World</div>

//// Auto spawn modal example:
<div id="my-auto-modal" class="js-auto-spawn">I will open on page load</div>

//// Ajax modal example:
<a href="url/to/ajax/modal" class="js-spawn-modal">I will spawn the modal at url/to/ajax/modal</a>

//// Close modal example:
<a href="#" class="js-close-modal">I will close the currently open modal</a>
<div class="js-close-modal">I too will close the currently open modal</div>
------------------------------------------------------------------------ */

var NERD = NERD || {};
NERD.Modals = {
    $overlay: undefined,
    $modal: undefined,
    $modalContent: undefined,
    $autoModal: undefined,
    href: undefined,

    init: function() {
        var self = this;
        var body = $('body');
        var $autoModal = $('.js-auto-spawn');

        self.$overlay = $('<div class="modal-overlay"></div>').appendTo(body);
        self.$modal = $('<div class="modal" aria-live="assertive"><a href="#" class="js-close-modal modal-close">Close</a><div class="modal-content"></div></div>').appendTo(body);
        self.$modalContent = self.$modal.find('div.modal-content');

        if ($autoModal.length) {
            self.$autoModal = $autoModal;
            self._spawnAutoModal();
        }

        self._bind();
    },

    _bind: function() {
        var self = this;

        $('body').on('click', 'a.js-spawn-modal',
            function(e) {
                var href = $(this).attr('href');
                if (href.indexOf('#') > -1) {
                    href = href.substr(href.lastIndexOf('#'), href.length);
                }
                self.href = href;
                e.preventDefault();
                self._loadContent();
            }
        );

        $('body').on('click', '.js-close-modal',
          function(e) {
                self.closeModal();
                e.preventDefault();
            }
        );

        self.$modal.on('submit','form',
          function(e) {
                // e.preventDefault();
                self.$modal.addClass('is-loading');
                // self._handleFormSubmit($(this));
            }
        );
    },

    // "Public method"
    // Argument is either the css ID of an element on page, or a url to ajax load
    // ID references must include '#' hash or will be treatead as a url
    loadModal: function(href) {
        var self = this;

        if(!href) {
            return false;
        }

        self.href = href;
        self._loadContent();
    },

    _spawnAutoModal: function() {
        var self = this;

        self.href = "#" + self.$autoModal.attr('id');
        self._loadContent();
    },

    _loadContent: function() {
        var self = this;

        self.href.charAt(0) !== '#' ? self._loadAjaxContent() : self._loadInlineContent();
    },

    _loadAjaxContent: function() {
        var self = this;

        $.ajax({
            url: self.href,
            dataType: 'html',
            success: function(data){
                self.$modalContent.html(data);
                self._cleanUrls();
                self._spawnModal();
            }
        });
    },

    _handleFormSubmit: function($form) {
        var self = this;
        var url = $form.attr('action');
        var data = null;

        $form.append('<input type="hidden" name="form-id" value="' + $form.attr('id') + '" />');
        data = $form.serialize();

        $.ajax({
            url: url,
            data: data,
            type: 'POST',
            dataType: 'html',
            success: function(response) {
                self.$modal.removeClass('is-loading');

                if ($(response).is('script')) {
                    self.$modalContent.append(response);
                    return;
                }

                self.$modalContent.html(response);
                self._cleanUrls();
                self._positionModal();
                self.$modal.show();
            }
        });
    },

    _cleanUrls: function() {
        var self = this;
        var $anchors = self.$modalContent.find('a');

        $anchors.each(
            function() {
                var $this = $(this);
                $this.attr('href', decodeURI($this.attr('href')));
            }
        );
    },

    _loadInlineContent: function() {
        var self = this;
        var content = $(self.href).clone(true, true).removeClass('hidden').removeClass('inline-modal').removeClass('js-auto-spawn');

        self.$modalContent.html('').append(content);
        self._cleanUrls();
        self._spawnModal();
    },

    _spawnModal: function() {
        var self = this;

        self._positionModal();
        self.$overlay.fadeTo(400, .80);
        self.$modal.fadeIn(400);
    },

    _positionModal: function() {
        var self = this;
        var measurement = self._measureModal();
        var leftOffset = Math.round(measurement.w/2);
        var topOffset = Math.round(measurement.h/2);
        var scrollOffset = $(window).scrollTop();

        self.$modal.css({
            'margin-left': -leftOffset,
            'margin-top': -topOffset
        });

        // If modal is positioned off screen, switch positioning
        if (measurement.t - topOffset - scrollOffset < 1000) { // originally was 10
            self.$modal.css({'margin-top': 'auto', 'top': scrollOffset + 80});
            self.$modal.addClass('modal-scroll');
        }
    },

    _measureModal: function() {
        var self = this;
        var measurement = {};

        self.$modal.css({
            'left-margin': -99999,
            'display': 'block'
        });

        measurement.w = self.$modal.outerWidth();
        measurement.h = self.$modal.outerHeight();
        measurement.t = self.$modal.position().top;

        self.$modal.attr('style', '');

        return measurement;
    },

    // Public
    closeModal: function() {
        var self = this;

        self.$overlay.fadeOut(400);

        self.$modal.fadeOut(400,
            function() {
                self.$modalContent.html('');
                self.$modal.removeClass('modal-scroll').attr('style', '');
            }
        );
    }
};
