(function( window, document, $, undefined ) {

    function NTicker( options ) {
        this.init.call( this, options );
    }

/* Public */
    NTicker.prototype = {
        init: function(options){
            this.options = $.extend({}, _options, options || {});

            _emptyCounter = this.options.empty*2;

            this.loadURL(this.options.url, this.options.dataType);
        },

        loadURL: function(url, dataType){
            var self = this;
            $.ajax({
                url: url,
                type: 'GET',
                dataType: dataType,
                success: function(data) {
                    _loadURLSuccess(data, self);
                }
            });
        }
    };

/* Private */

    // Default NTicker options
    var _options = {
        url: '',
        dataType: '',
        appendTo: '',
        empty: 4,
        duration: 5000,
        printheadDuration: 5000,
        overlayImg: false,
        overlayEase: 80
    };

    var _htmlStr = [];
    var _emptyCounter;
    var _removedEmpties = false;
    var _alternateCall = false;
    var _fixOdds = true;

    var _loadURLSuccess = function(data, scope) {
        _parseData(data, scope);

        // Append to div
        scope.options.appendTo.append(_htmlStr.reverse().join(''));
        _animate(scope);
    };

    var _parseData = function(data, scope) {

        // Create empty beginning ones
        for (var count = 0; count < scope.options.empty; count++) {
            _htmlStr.push(
                '<div class="row' +
                (count % 2 ? " alt" : "") +
                ' empty"></div>'
            );
        }

        $(data).find('message').each(function(i,n){
            $this = $(this);
            _htmlStr.push(
                '<div class="row' +
                (count % 2 ? " alt" : "") +
                '"><h3>' +
                $this.find('type').text().toLowerCase() +
                '</h3><p><a href="' +
                $this.find('url').text() +
                '">' +
                $this.find('subject').text() +
                '</a></p></div>'
            );

            count++;
        });

    };

    var _animate = function(scope){

        scope.options.appendTo.animate(
            {
                bottom: '-=21'
            },
            scope.options.duration,
            function() {
                var rows = scope.options.appendTo.find('.row');

                if (_emptyCounter >= 0) {
                    _emptyCounter--;
                    rows.first().css("bottom", -(41 * (scope.options.empty + 1)) + "px");
                    _printHeadCallback(scope);
                    return;
                }

                if (_alternateCall == false)
                {
                    _alternateCall = true;
                } else {
                    _alternateCall = false;

                    if (_fixOdds == false) {
                        _fixOdds = true;
                    } else {
                        _fixOdds = false;
                        rowParent = rows.parent();
                        rowParent.children('.row:not(.alt):nth-child(odd)').addClass('alt');
                        rowParent.children('.alt:nth-child(even)').removeClass('alt');
                    }
                    if (!rows.last().hasClass('empty')) {
                         scope.options.appendTo
                             .prepend(rows.last())
                             .css("bottom", -(41 * (scope.options.empty + 1)) + "px");
                     } else {
                         scope.options.appendTo
                             .prepend(rows.slice(0, -scope.options.empty).last())
                             .css("bottom", -(41 * (scope.options.empty + 1)) + "px");
                     }
                 }
                _printHeadCallback(scope);
            }
        );
    }

    var _printHeadCallback = function(scope) {
        if (scope.options.overlayImg) {
            if (scope.options.overlayImg.css('left') 
                >= scope.options.overlayEase+'px') {
                scope.options.overlayImg.animate({
                    left: "-="+scope.options.overlayEase
                }, scope.options.printheadDuration, function() {
                    _animate(scope);
                });
            } else {
                    scope.options.overlayImg.animate({
                        left: "+="+scope.options.overlayEase
                    }, scope.options.printheadDuration, function() {
                        _animate(scope);
                });
            }
        } else {
            _animate(scope);
        }
    }

    // Expose NTicker to the global object
    window.NTicker = NTicker;

})(window, document, jQuery);
