var MethodDNAWidget = {
	dataList: [],
	allRoles: ["dna-left","dna-left","dna-left","dna-right",  "dna-left","dna-left","dna-left","dna-left",  "dna-right","dna-right","dna-right","dna-right"],
	sampleA: ["dna-left","dna-left","dna-left","dna-right",  "dna-left","dna-right","dna-left","dna-right",  "dna-right","dna-right","dna-right","dna-right"],
	sampleB: ["dna-left","dna-left","dna-left","dna-right",  "dna-right","dna-left","dna-left","dna-left",  "dna-right","dna-right","dna-right","dna-left"],
	sampleC: ["dna-left","dna-left","dna-left","dna-left",  "dna-right","dna-right","dna-right","dna-right",  "dna-left","dna-left","dna-left","dna-right"],
	
	init: function()
	{
		//Sets the default css styles for the DNA chart
		MethodDNAWidget.changeDNA( MethodDNAWidget.allRoles );
		
		//List of css styles array's.
		MethodDNAWidget.dataList = [MethodDNAWidget.allRoles, MethodDNAWidget.sampleA, MethodDNAWidget.sampleB, MethodDNAWidget.sampleC];
		
		//Adds the array data to link element so it will be easy to grab when clicked
		$('.method #dna-nav li a').each(function(index) {
			 $(this).data("styles", MethodDNAWidget.dataList[index] );
		});
		
		//Gives each li an id so we can use it later on click of the element.
		$('.method #dna-frame li').each(function(index) {
			$(this).data("id", index );
		});
		
		$('.method #dna-wrapper #dna-frame ul li').click(function(e) {
			var id = $(this).data("id");
			
			MethodDNAWidget.hidePopups();
			
			
			$('.method #dna-wrapper .popup-text h3').html( $(this).children("span").first().html() );
			$('.method #dna-wrapper .popup-text div').html( $(this).children("div").first().html() );
			
			//console.log( $(this).parent().children() );//.addClass("selected");
			
			//$(this).parent().children().addClass("selected");
			
			
			if(id == 0 || id == 1 || id == 2){
				// Only do the first three
				var FIRST_THREE_CHILDREN = 3;
				var children = $(this).parent().children();
				for (var i = 0; i < FIRST_THREE_CHILDREN; i++) {
					$(children[i]).addClass("selected");
				}

				$('.method #dna-wrapper #three-popup-wrapper').show();
			}else{
				$(this).addClass("selected");
				$('.method #dna-wrapper #single-popup-wrapper').css('top', $(this).position().top - 56);
				$('.method #dna-wrapper #single-popup-wrapper').show();
			}
			
			return false;
		});
		
		//On click it will change the DNA layout
		$('.method #dna-wrapper #dna-nav li a').click(function() {
			MethodDNAWidget.hidePopups();
			$('.method #dna-wrapper #dna-nav li a').removeClass("selected");
			$(this).addClass("selected");
			MethodDNAWidget.changeDNA( $(this).data("styles") );
			return false;
		});
		
		$('.method #dna-wrapper .close').click(function() {
			MethodDNAWidget.hidePopups();
			return false;
		});
	},

    changeDNA: function(array)
    {
        $('.method #dna-frame li').removeClass().each(function(index) {
            var class_name = array[index];
            $(this).removeClass('dna-left').removeClass('dna-right');
            $(this).addClass( class_name );
        });
    },
	
	hidePopups: function()
	{
		$('.method #dna-wrapper #dna-frame ul li').removeClass("selected");
		$('.method #dna-wrapper #single-popup-wrapper').hide();
		$('.method #dna-wrapper #three-popup-wrapper').hide();
	}

}

