NERD.RadioToggler = {
    /*
    All parameters are jQuery selectors.  Feed in the radio button that correlates to 'show' as true,
    feed in the radio button that correlates to 'hide' as false, and then feed in the container element
    to toggle.
    */
    init: function(radio_button_show, radio_button_hide, fields_to_toggle, parent_container_selector, class_to_apply) {
        radio_button_hide.click(function() {
            if (radio_button_hide.is(':checked')) {
                fields_to_toggle.slideUp();
                if (parent_container_selector !== undefined) {
                    radio_button_show.closest(parent_container_selector).removeClass(class_to_apply);
                }
            }
        });
        radio_button_show.click(function() {
            if (radio_button_show.is(':checked')) {
                fields_to_toggle.slideDown();
                
                if (parent_container_selector !== undefined) {
                radio_button_show.closest(parent_container_selector).addClass(class_to_apply);
                }
            }
        });
        // Handle default page load case.
        if (!radio_button_show.is(':checked')) {
            fields_to_toggle.hide();
        }
    }
};
